// Configure ClinicalTrials.gov REST API v2 query (zero API keys required)
const condition = 'oncology';
const status = 'RECRUITING';
const sponsorClass = 'INDUSTRY'; // INDUSTRY | NIH | OTHER
const pageSize = 10;
const requestUrl = `https://clinicaltrials.gov/api/v2/studies?query.cond=${encodeURIComponent(condition)}&filter.overallStatus=${encodeURIComponent(status)}&filter.advanced=${encodeURIComponent('AREA[LeadSponsorClass]' + sponsorClass)}&pageSize=${pageSize}`;

return [{
  json: { condition, status, sponsorClass, pageSize, requestUrl },
}];

// Normalize ClinicalTrials.gov REST v2 recruiting studies into biotech sponsor leads
const payload = $input.first().json || {};
const studies = Array.isArray(payload.studies) ? payload.studies : [];
const out = [];

for (const study of studies) {
  const ps = study.protocolSection || {};
  const ident = ps.identificationModule || {};
  const statusMod = ps.statusModule || {};
  const sponsor = (ps.sponsorCollaboratorsModule || {}).leadSponsor || {};
  const design = ps.designModule || {};
  const contacts = ps.contactsLocationsModule || {};
  const central = Array.isArray(contacts.centralContacts) ? contacts.centralContacts : [];
  const locations = Array.isArray(contacts.locations) ? contacts.locations : [];
  const primaryContact = central.find((c) => c && c.email) || central[0] || {};
  const nctId = ident.nctId || null;

  out.push({
    json: {
      nctId,
      briefTitle: ident.briefTitle || '',
      sponsorName: sponsor.name || '',
      sponsorClass: sponsor.class || '',
      phases: Array.isArray(design.phases) ? design.phases : [],
      enrollment: (design.enrollmentInfo || {}).count ?? null,
      overallStatus: statusMod.overallStatus || '',
      centralContactsCount: central.length,
      locationsCount: locations.length,
      primaryContactName: primaryContact.name || null,
      primaryContactEmail: primaryContact.email || null,
      primaryContactPhone: primaryContact.phone || null,
      studyUrl: nctId ? `https://clinicaltrials.gov/study/${nctId}` : null,
      agentSummary: `${nctId}: ${sponsor.name || 'Unknown'} (${(design.phases || []).join('/') || 'N/A'}) — ${ident.briefTitle || ''}${primaryContact.email ? ' | ' + primaryContact.email : ''}`,
    },
  });
}

return out.length ? out : [{ json: { status: 'no_studies_found' } }];
